CREATE TABLE "clientes" (
    "idCliente"             int           GENERATED BY DEFAULT AS IDENTITY,
    "cedulaCliente"          varchar(10)   NOT NULL,
    "nombresCliente"         varchar(100)  NOT NULL,
    "apellidosCliente"       varchar(100)  NOT NULL,
    "fechaNacimiento"        date          NOT NULL,
    "direccionCliente"       varchar(200)  NOT NULL,
    "ciudadCliente"          varchar(50)   NOT NULL,
    "telefonoCliente"        varchar(10)   NOT NULL,
    "correoCliente"          varchar(100),
    "estadoCliente"          varchar(8)    NOT NULL DEFAULT 'ACTIVO',
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkCliente" PRIMARY KEY ("idCliente"),
    CONSTRAINT "uqClienteCedula" UNIQUE ("cedulaCliente"),
    CONSTRAINT "ckClienteCedula" CHECK ("cedulaCliente" ~ '^[0-9]{10}$'),
    CONSTRAINT "ckClienteTelefono" CHECK ("telefonoCliente" ~ '^[0-9]{9,10}$'),
    CONSTRAINT "ckClienteCorreo" CHECK ("correoCliente" IS NULL OR "correoCliente" ~ '^[^@ ]+@[^@ ]+\.[^@ ]+$'),
    CONSTRAINT "ckClienteEstado" CHECK ("estadoCliente" IN ('ACTIVO', 'INACTIVO')),
    CONSTRAINT "ckClienteAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "cuentas" (
    "idCuenta"              int           GENERATED BY DEFAULT AS IDENTITY,
    "idCliente"             int           NOT NULL,
    "numeroCuenta"          varchar(20)   NOT NULL,
    "tipoCuenta"            varchar(9)    NOT NULL,
    "saldoCuenta"           numeric(12,2) NOT NULL DEFAULT 0,
    "fechaApertura"         date          NOT NULL,
    "estadoCuenta"          varchar(8)    NOT NULL DEFAULT 'ACTIVA',
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkCuenta" PRIMARY KEY ("idCuenta"),
    CONSTRAINT "uqCuentaNumero" UNIQUE ("numeroCuenta"),
    CONSTRAINT "fkCuentaCliente" FOREIGN KEY ("idCliente") REFERENCES "clientes" ("idCliente"),
    CONSTRAINT "ckCuentaNumero" CHECK ("numeroCuenta" ~ '^[0-9]{10,20}$'),
    CONSTRAINT "ckCuentaTipo" CHECK ("tipoCuenta" IN ('AHORROS', 'CORRIENTE')),
    CONSTRAINT "ckCuentaSaldo" CHECK ("saldoCuenta" >= 0),
    CONSTRAINT "ckCuentaEstado" CHECK ("estadoCuenta" IN ('ACTIVA', 'INACTIVA', 'CERRADA')),
    CONSTRAINT "ckCuentaAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "movimientos" (
    "idMovimiento"          int           GENERATED BY DEFAULT AS IDENTITY,
    "idCuenta"              int           NOT NULL,
    "tipoMovimiento"        varchar(7)    NOT NULL,
    "conceptoMovimiento"    varchar(20)   NOT NULL,
    "montoMovimiento"       numeric(12,2) NOT NULL,
    "saldoPosterior"        numeric(12,2) NOT NULL,
    "fechaMovimiento"       date          NOT NULL,
    "fechaHoraMovimiento"   timestamp     NOT NULL,
    "uuidTransaccion"       uuid          NOT NULL DEFAULT gen_random_uuid(),
    "numeroOperacion"       varchar(20),
    "canal"                 varchar(20),
    "referencia"            varchar(100),
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkMovimiento" PRIMARY KEY ("idMovimiento"),
    CONSTRAINT "uqMovimientoUuid" UNIQUE ("uuidTransaccion"),
    CONSTRAINT "fkMovimientoCuenta" FOREIGN KEY ("idCuenta") REFERENCES "cuentas" ("idCuenta"),
    CONSTRAINT "ckMovimientoTipo" CHECK ("tipoMovimiento" IN ('CREDITO', 'DEBITO')),
    CONSTRAINT "ckMovimientoConcepto" CHECK ("conceptoMovimiento" IN ('DEPOSITO', 'RETIRO', 'DESEMBOLSO', 'COBRO_CUOTA', 'DEVOLUCION_SOBREPAGO')),
    CONSTRAINT "ckMovimientoConceptoTipo" CHECK (
        ("conceptoMovimiento" IN ('DEPOSITO', 'DESEMBOLSO', 'DEVOLUCION_SOBREPAGO') AND "tipoMovimiento" = 'CREDITO')
     OR ("conceptoMovimiento" IN ('RETIRO', 'COBRO_CUOTA') AND "tipoMovimiento" = 'DEBITO')),
    CONSTRAINT "ckMovimientoMonto" CHECK ("montoMovimiento" > 0 AND "saldoPosterior" >= 0),
    CONSTRAINT "ckMovimientoCanal" CHECK ("canal" IS NULL OR "canal" IN ('VENTANILLA', 'BANCA_WEB', 'DEBITO_AUTOMATICO', 'TRANSFERENCIA')),
    CONSTRAINT "ckMovimientoPrestamo" CHECK (("conceptoMovimiento" IN ('DESEMBOLSO', 'COBRO_CUOTA', 'DEVOLUCION_SOBREPAGO')) = ("numeroOperacion" IS NOT NULL)),
    CONSTRAINT "ckMovimientoCobro" CHECK (("conceptoMovimiento" = 'COBRO_CUOTA') = ("canal" IS NOT NULL)),
    CONSTRAINT "ckMovimientoAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE INDEX "ixCuentaCliente" ON "cuentas" ("idCliente");
CREATE INDEX "ixMovimientoCuenta" ON "movimientos" ("idCuenta", "fechaMovimiento");
CREATE INDEX "ixMovimientoCobroDia" ON "movimientos" ("fechaMovimiento") WHERE "conceptoMovimiento" = 'COBRO_CUOTA';
